CREATE SCHEMA community_before_split;
LOCK TABLE clubs,club_members,community_topics,community_replies,community_checkins IN ACCESS EXCLUSIVE MODE;
CREATE TABLE community_before_split.backup_clubs AS TABLE public.clubs;
CREATE TABLE community_before_split.backup_club_members AS TABLE public.club_members;
CREATE TABLE community_before_split.backup_community_topics AS TABLE public.community_topics;
CREATE TABLE community_before_split.backup_community_replies AS TABLE public.community_replies;
CREATE TABLE community_before_split.backup_community_checkins AS TABLE public.community_checkins;
ALTER TABLE public.clubs SET SCHEMA community_before_split;
ALTER TABLE public.club_members SET SCHEMA community_before_split;
ALTER TABLE public.community_topics SET SCHEMA community_before_split;
ALTER TABLE public.community_replies SET SCHEMA community_before_split;
ALTER TABLE public.community_checkins SET SCHEMA community_before_split;
CREATE TABLE mentor_verifications(user_id text PRIMARY KEY REFERENCES ledgerline_accounts(firebase_uid),status text NOT NULL CHECK(status IN ('pending','approved','rejected')));
CREATE TABLE mentor_entitlements(user_id text PRIMARY KEY REFERENCES ledgerline_accounts(firebase_uid),active boolean NOT NULL DEFAULT false,expires_at timestamptz);
CREATE TABLE mentor_plan_requests(user_id text PRIMARY KEY REFERENCES ledgerline_accounts(firebase_uid),requested_at timestamptz DEFAULT now());
CREATE TABLE clubs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_id text NOT NULL REFERENCES ledgerline_accounts(firebase_uid) ON DELETE CASCADE,name text NOT NULL,description text NOT NULL,location text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now(),
join_mode text NOT NULL DEFAULT 'open' CHECK(join_mode IN ('open','request','invite')), visibility text NOT NULL DEFAULT 'public' CHECK(visibility IN ('public','private')),invite_code uuid NOT NULL UNIQUE DEFAULT gen_random_uuid());
CREATE TABLE club_members(user_id text NOT NULL REFERENCES ledgerline_accounts(firebase_uid) ON DELETE CASCADE,club_id uuid NOT NULL REFERENCES clubs ON DELETE CASCADE,joined_at timestamptz NOT NULL DEFAULT now(), stats_opt_in boolean NOT NULL DEFAULT false,PRIMARY KEY(user_id,club_id));
CREATE TABLE club_requests(user_id text NOT NULL REFERENCES ledgerline_accounts(firebase_uid) ON DELETE CASCADE,club_id uuid NOT NULL REFERENCES clubs ON DELETE CASCADE,PRIMARY KEY(user_id,club_id));
CREATE TABLE club_posts(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,club_id uuid NOT NULL REFERENCES clubs ON DELETE CASCADE,author_id text NOT NULL REFERENCES ledgerline_accounts(firebase_uid),kind text NOT NULL,body text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE club_replies(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,topic_id bigint NOT NULL REFERENCES club_posts ON DELETE CASCADE,user_id text NOT NULL REFERENCES ledgerline_accounts(firebase_uid),body text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE club_checkins(topic_id bigint NOT NULL REFERENCES club_posts ON DELETE CASCADE,user_id text NOT NULL REFERENCES ledgerline_accounts(firebase_uid),PRIMARY KEY(topic_id,user_id));
INSERT INTO clubs(id,owner_id,name,description,location,created_at) SELECT id,owner_id,name,description,location,created_at FROM community_before_split.clubs WHERE kind='club';
INSERT INTO club_members(user_id,club_id,joined_at) SELECT user_id,club_id,joined_at FROM community_before_split.club_members WHERE club_id IN(SELECT id FROM clubs);
INSERT INTO club_posts SELECT id,club_id,author_id,kind,body,created_at FROM community_before_split.community_topics WHERE club_id IN(SELECT id FROM clubs);
INSERT INTO club_replies SELECT * FROM community_before_split.community_replies WHERE topic_id IN(SELECT id FROM club_posts);
INSERT INTO club_checkins SELECT * FROM community_before_split.community_checkins WHERE topic_id IN(SELECT id FROM club_posts);
SELECT setval(pg_get_serial_sequence('club_posts','id'),coalesce(max(id),1),max(id) IS NOT NULL) FROM club_posts;
SELECT setval(pg_get_serial_sequence('club_replies','id'),coalesce(max(id),1),max(id) IS NOT NULL) FROM club_replies;
CREATE TABLE spaces(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_id text NOT NULL REFERENCES ledgerline_accounts(firebase_uid) ON DELETE CASCADE,name text NOT NULL,description text NOT NULL,location text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now(),
join_mode text NOT NULL DEFAULT 'invite' CHECK(join_mode IN ('open','request','invite')), visibility text NOT NULL DEFAULT 'private' CHECK(visibility IN ('public','private')),invite_code uuid NOT NULL UNIQUE DEFAULT gen_random_uuid());
CREATE TABLE space_members(user_id text NOT NULL REFERENCES ledgerline_accounts(firebase_uid) ON DELETE CASCADE,space_id uuid NOT NULL REFERENCES spaces ON DELETE CASCADE,joined_at timestamptz NOT NULL DEFAULT now(), stats_opt_in boolean NOT NULL DEFAULT false,PRIMARY KEY(user_id,space_id));
CREATE TABLE space_requests(user_id text NOT NULL REFERENCES ledgerline_accounts(firebase_uid) ON DELETE CASCADE,space_id uuid NOT NULL REFERENCES spaces ON DELETE CASCADE,PRIMARY KEY(user_id,space_id));
CREATE TABLE space_posts(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,space_id uuid NOT NULL REFERENCES spaces ON DELETE CASCADE,author_id text NOT NULL REFERENCES ledgerline_accounts(firebase_uid),kind text NOT NULL,body text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE space_replies(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,topic_id bigint NOT NULL REFERENCES space_posts ON DELETE CASCADE,user_id text NOT NULL REFERENCES ledgerline_accounts(firebase_uid),body text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE space_checkins(topic_id bigint NOT NULL REFERENCES space_posts ON DELETE CASCADE,user_id text NOT NULL REFERENCES ledgerline_accounts(firebase_uid),PRIMARY KEY(topic_id,user_id));
INSERT INTO spaces(id,owner_id,name,description,location,created_at) SELECT id,owner_id,name,description,location,created_at FROM community_before_split.clubs WHERE kind='space';
INSERT INTO space_members(user_id,space_id,joined_at) SELECT user_id,club_id,joined_at FROM community_before_split.club_members WHERE club_id IN(SELECT id FROM spaces);
INSERT INTO space_posts SELECT id,club_id,author_id,kind,body,created_at FROM community_before_split.community_topics WHERE club_id IN(SELECT id FROM spaces);
INSERT INTO space_replies SELECT * FROM community_before_split.community_replies WHERE topic_id IN(SELECT id FROM space_posts);
INSERT INTO space_checkins SELECT * FROM community_before_split.community_checkins WHERE topic_id IN(SELECT id FROM space_posts);
SELECT setval(pg_get_serial_sequence('space_posts','id'),coalesce(max(id),1),max(id) IS NOT NULL) FROM space_posts;
SELECT setval(pg_get_serial_sequence('space_replies','id'),coalesce(max(id),1),max(id) IS NOT NULL) FROM space_replies;
CREATE TABLE space_assignments(post_id bigint PRIMARY KEY REFERENCES space_posts ON DELETE CASCADE);
CREATE TABLE space_announcements(post_id bigint PRIMARY KEY REFERENCES space_posts ON DELETE CASCADE);
INSERT INTO space_assignments SELECT id FROM space_posts WHERE kind='goal';
ALTER TABLE community_before_split.community_topics ADD COLUMN IF NOT EXISTS group_kind text CHECK(group_kind IN ('club','space'));
UPDATE community_before_split.community_topics t SET group_kind=c.kind FROM community_before_split.clubs c WHERE c.id=t.club_id;
